import{_ as s,o as a,c as o,af as e}from"./chunks/framework.Dt3O48XQ.js";const h=JSON.parse('{"title":"安装指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":null}'),n={name:"guide/installation.md"};function d(r,t,i,c,l,p){return a(),o("div",null,[...t[0]||(t[0]=[e(`<h1 id="安装指南" tabindex="-1">安装指南 <a class="header-anchor" href="#安装指南" aria-label="Permalink to &quot;安装指南&quot;">​</a></h1><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><ul><li>Node.js &gt;= 20.9.0</li><li>MySQL / MariaDB</li><li>Redis（<strong>匹配、聊天等队列能力需要</strong>；仅调 HTTP 可暂不配，跑 <code>MatchmakingDemo</code> 请启用）</li></ul><h2 id="安装依赖" tabindex="-1">安装依赖 <a class="header-anchor" href="#安装依赖" aria-label="Permalink to &quot;安装依赖&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h2 id="配置环境变量" tabindex="-1">配置环境变量 <a class="header-anchor" href="#配置环境变量" aria-label="Permalink to &quot;配置环境变量&quot;">​</a></h2><p>在项目根目录创建 <strong><code>.env.development</code></strong>（本地开发）或 <strong><code>.env.production</code></strong>（生产），服务端会按 <code>NODE_ENV</code> 等规则加载；加载顺序与优先级见 <a href="/xcs.github.io/guide/configuration.html">配置说明</a> 开头几节。</p><p>下面是一份<strong>最小可跑</strong>示例；<strong>各键含义</strong>如下表（表中 <code>your_*</code> 仅为占位，请换成你本机 MySQL 与自生成的密钥）。</p><table tabindex="0"><thead><tr><th>变量</th><th>是什么</th></tr></thead><tbody><tr><td><strong><code>NODE_ENV</code></strong></td><td>Node 运行环境。写成 <strong><code>development</code></strong> 时，会优先读 <strong><code>.env.development</code></strong>，并启用开发期常见行为（与 <code>src/config</code> 中判断一致）。</td></tr><tr><td><strong><code>PORT</code></strong></td><td><strong>HTTP API + Colyseus WebSocket</strong> 共用的监听端口；默认常用 <strong>2567</strong>，即浏览器访问 <strong><code>http://localhost:2567</code></strong>、Swagger <strong><code>/api-docs</code></strong> 等。</td></tr><tr><td><strong><code>DB_HOST</code></strong></td><td><strong>MySQL / MariaDB</strong> 主机地址，本机一般为 <code>localhost</code>。</td></tr><tr><td><strong><code>DB_PORT</code></strong></td><td>数据库端口，MySQL 默认 <strong>3306</strong>。</td></tr><tr><td><strong><code>DB_USERNAME</code></strong> / <strong><code>DB_PASSWORD</code></strong></td><td>数据库登录账号与密码；密码勿提交到 Git。</td></tr><tr><td><strong><code>DB_DATABASE</code></strong></td><td>要连接的<strong>数据库名</strong>（需先在 MySQL 里建好空库或已有库）。完整表名、实体与迁移见 <a href="/xcs.github.io/guide/project-structure.html">项目结构</a>。</td></tr><tr><td><strong><code>JWT_SECRET</code></strong></td><td>签发 <strong>JWT 访问令牌</strong>用的<strong>对称密钥</strong>（与 HTTP 登录、<strong><code>@RequireAuth()</code> 进房</strong>里校验的 token 同源）。生产环境必须改为<strong>足够长的随机串</strong>，切勿使用示例里的占位值。</td></tr><tr><td><strong><code>JWT_EXPIRES_IN</code></strong></td><td>访问令牌<strong>有效期</strong>的字符串写法（如 <code>1h</code>、<code>24h</code>），交给 <code>jsonwebtoken</code> 等库的 <code>expiresIn</code>；<strong>刷新令牌</strong>、<strong><code>JWT_REFRESH_*</code></strong> 等见 <a href="/xcs.github.io/guide/configuration.html">配置说明</a> 中的 <strong>「Redis 与 JWT」</strong> 一节。</td></tr></tbody></table><p>更多项（<strong><code>DB_TYPE</code></strong>、<strong><code>DB_SYNCHRONIZE</code></strong>、<strong>Redis</strong>、聊天/匹配相关变量等）见 <a href="/xcs.github.io/guide/configuration.html">配置说明</a>。</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NODE_ENV=development</span></span>
<span class="line"><span>PORT=2567</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DB_HOST=localhost</span></span>
<span class="line"><span>DB_PORT=3306</span></span>
<span class="line"><span>DB_USERNAME=root</span></span>
<span class="line"><span>DB_PASSWORD=your_password</span></span>
<span class="line"><span>DB_DATABASE=your_database</span></span>
<span class="line"><span></span></span>
<span class="line"><span>JWT_SECRET=your_jwt_secret_key</span></span>
<span class="line"><span>JWT_EXPIRES_IN=1h</span></span></code></pre></div><h2 id="启动开发环境" tabindex="-1">启动开发环境 <a class="header-anchor" href="#启动开发环境" aria-label="Permalink to &quot;启动开发环境&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><h2 id="验证运行" tabindex="-1">验证运行 <a class="header-anchor" href="#验证运行" aria-label="Permalink to &quot;验证运行&quot;">​</a></h2><ul><li>Swagger: <code>http://localhost:2567/api-docs</code></li><li>首页静态资源: <code>http://localhost:2567/</code></li></ul><p>服务可用后，再继续阅读 <a href="/xcs.github.io/guide/configuration.html">配置说明</a>。</p>`,16)])])}const u=s(n,[["render",d]]);export{h as __pageData,u as default};
